-- Northern Stranglethorn: creature abilities
-- Most of the zone's creatures (the Kurzen, Bloodscalp and Skullsplitter trolls, the Mosh'Ogg, the Saltscale and Murkgill murlocs,
-- the panthers, tigers, raptors and gorillas) had no AI or ran classic rows. Port their abilities from the Cataclysm data, and from
-- the classic data where Cataclysm has none. The creatures no reference scripts (the Kurzen chiefs, Gurubashi Crushers, the rebel
-- camp, Nesingwary's hired guns, the guards) cast their sniffed spells (creature_template spell1-8).

SET @ENTRIES := '588,595,660,667,669,670,671,672,678,679,680,681,682,684,687,689,691,699,702,709,710,736,781,782,818,873,875,877,879,905,938,940,942,976,979,1059,1061,1062,1144,4260,4457,4458,4459,4460,4723,14488,17207,26204';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);

-- Creatures without reference data: their sniffed creature_template spell1-8
SET @ENTRIES := '723,784,978,42858,42872,43049,43050,43910,43911,43912,43913,51521,51533,51658,51662,51917,52184,52224,52404,52982,53000,53166';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
